/** A series colour is a token name, never a hex, so it follows the theme. */
export type ChartColor =
  | 'chart-1'
  | 'chart-2'
  | 'chart-3'
  | 'chart-4'
  | 'chart-5'
  | 'chart-6'
  | 'chart-7'
  | 'chart-8'
  | 'info'
  | 'success'
  | 'warning'
  | 'danger'
  | 'neutral'

export interface ChartSeries {
  /** The field in each data row that holds this series' value. */
  key: string
  label: string
  /** Defaults to the palette, in order: chart-1, chart-2, … */
  color?: ChartColor
}

/* --warning is a fill for dark labels and only reaches 2.15:1 on a white card;
   a mark needs 3:1 (WCAG 1.4.11), which --warning-indicator is measured for. */
export const colorVar = (color: ChartColor) =>
  color === 'warning' ? 'var(--warning-indicator)' : color === 'neutral' ? 'var(--muted-foreground)' : `var(--${color})`

export const paletteColor = (index: number): ChartColor => `chart-${(index % 8) + 1}` as ChartColor

// Built once: a chart formats every tick, legend item and tooltip row on each pointer move.
const compact = new Intl.NumberFormat(undefined, { notation: 'compact', maximumFractionDigits: 2 })
const share = new Intl.NumberFormat(undefined, { style: 'percent', maximumFractionDigits: 1 })
const times = new Map<string | undefined, Intl.DateTimeFormat>()

/** "3.15K", in the viewer's locale. */
export const formatCompact = (value: number) => compact.format(value)

/** "Oct 19, 12:00", in the viewer's locale and time zone, or UTC. */
export function formatTime(date: Date, timeZone?: 'UTC') {
  let f = times.get(timeZone)
  if (!f) {
    f = new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23', timeZone })
    times.set(timeZone, f)
  }
  return f.format(date)
}

export const formatShare = (value: number) => share.format(value)

export interface Slice {
  label: string
  value: number
  color?: ChartColor
}

/**
 * Past `max` slices, or below `minShare` of the total, a pie stops being
 * readable: those slices merge into one "Other" in the neutral colour.
 */
export function groupSlices(data: Slice[], max = 6, minShare = 0.03): (Slice & { color: ChartColor })[] {
  const total = data.reduce((sum, d) => sum + d.value, 0)
  const sorted = [...data].sort((a, b) => b.value - a.value)
  const fits = (d: Slice) => total === 0 || d.value / total >= minShare
  const keep = sorted.length <= max && sorted.every(fits) ? sorted : sorted.filter((d, i) => i < max - 1 && fits(d))
  const rest = sorted.slice(keep.length)
  const slices = keep.map((d, i) => ({ ...d, color: d.color ?? paletteColor(i) }))
  if (rest.length)
    slices.push({ label: `Other (${rest.length})`, value: rest.reduce((sum, d) => sum + d.value, 0), color: 'neutral' })
  return slices
}

/* Shared by every chart. Marks take their colour from --chart-1…8 (or a
   status token) through the fill/stroke attribute the component sets, so a
   theme switch repaints them without React rendering again. */

.chart {
  display: grid;
  gap: var(--space-inline);
  min-inline-size: 0;
  margin: 0;
  font-family: var(--font-sans);
  color: var(--foreground);
}

.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-inline);
}

.title {
  font-size: var(--text-body);
  line-height: var(--leading-body);
  font-weight: 600;
}

/* Legend */
.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 0 var(--space-stack);
  margin: 0;
  margin-inline-start: calc(-1 * var(--space-1-5));
  padding: 0;
  list-style: none;
}

.legendVertical {
  flex-direction: column;
  flex: 1 1 12rem;
  min-inline-size: 0;
  margin-inline-start: 0;
}

.legendItem {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1-5);
  inline-size: 100%;
  padding: var(--space-stack) var(--space-1-5);
  border: 0;
  border-radius: var(--radius-field);
  background: transparent;
  font: inherit;
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  color: var(--subtle-foreground);
  text-align: start;
}

button.legendItem {
  cursor: var(--cursor-button);
}

/* On touch screens the hit area grows to 44px without the item growing with it. */
@media (pointer: coarse) {
  button.legendItem {
    position: relative;
  }

  button.legendItem::after {
    content: '';
    position: absolute;
    inset: 50% auto auto 50%;
    inline-size: max(100%, var(--target-coarse));
    block-size: max(100%, var(--target-coarse));
    translate: -50% -50%;
  }
}

button.legendItem:hover,
.legendVertical .legendItem:hover {
  background: var(--hover-overlay);
}

button.legendItem:focus-visible {
  outline: var(--focus-width) solid var(--ring);
  outline-offset: var(--focus-offset-inset);
}

/* Off: struck through, with a hollow swatch. Not a lighter grey: on the hover
   fill --muted-foreground drops under 4.5:1. */
button.legendItem[aria-pressed='false'] .legendLabel {
  text-decoration: line-through;
}

button.legendItem[aria-pressed='false'] .swatch {
  background: transparent;
  box-shadow: inset 0 0 0 1.5px var(--swatch);
}

.legendLabel {
  min-inline-size: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.legendValue {
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  color: var(--foreground);
}

.legendVertical .legendValue {
  margin-inline-start: auto;
  padding-inline-start: var(--space-cluster);
}

.swatch {
  --swatch: currentColor;
  flex: none;
  inline-size: var(--space-2);
  block-size: var(--space-2);
  border-radius: var(--radius-pill);
  background: var(--swatch);
}

/* Plot */
.plot {
  position: relative;
  min-inline-size: 0;
}

.plot svg {
  display: block;
  overflow: visible;
}

.axis {
  font-size: var(--text-body-xs);
  font-variant-numeric: tabular-nums;
  fill: var(--muted-foreground);
}

.grid {
  stroke: var(--border);
  stroke-dasharray: 2 3;
}

.tick {
  stroke: var(--border);
}

.series {
  transition: opacity var(--duration-base);
}

.dim {
  opacity: 0.2;
}

.line,
.lineDashed {
  fill: none;
  stroke-width: 1.5;
  stroke-linejoin: round;
}

.lineDashed {
  stroke-dasharray: 3 3;
}

.area {
  fill-opacity: 0.12;
}

/* A gap of card colour between stacked segments, so each one meets the card
   rather than its neighbour: the 3:1 of WCAG 1.4.11 is against the card. */
.bar {
  stroke: var(--card);
  stroke-width: 1;
}

.partial {
  fill-opacity: 0.45;
}

.cursor {
  stroke: var(--control-border);
}

.cursorBand {
  fill: var(--hover-overlay);
}

.dot {
  stroke: var(--card);
  stroke-width: 1.5;
}

.slice {
  stroke: var(--card);
  stroke-width: 1.5;
  transition: opacity var(--duration-base);
}

.pieBody {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-group);
}

.pieBody svg {
  flex: none;
}

.centerTotal {
  font-size: var(--text-heading-sm);
  font-weight: 600;
  fill: var(--foreground);
}

.centerLabel {
  font-size: var(--text-body-sm);
  fill: var(--muted-foreground);
}

/* Tooltip: follows the crosshair, flips to the start side past the middle. */
.tooltip {
  position: absolute;
  z-index: var(--layer-tooltip);
  display: grid;
  gap: var(--space-1);
  min-inline-size: 9rem;
  padding: var(--space-2) var(--space-2-5);
  border: 1px solid var(--border);
  border-radius: var(--radius-field);
  background: var(--popover);
  box-shadow: var(--elevation-md);
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  color: var(--popover-foreground);
  pointer-events: none;
  transform: translateX(var(--space-3));
}

.tooltipFlip {
  transform: translateX(calc(-100% - var(--space-3)));
}

.tooltipHead {
  color: var(--muted-foreground);
}

.tooltipRow {
  display: flex;
  align-items: center;
  gap: var(--space-1-5);
}

.tooltipRow b {
  margin-inline-start: auto;
  padding-inline-start: var(--space-3);
  font-weight: 500;
  font-variant-numeric: tabular-nums;
}

.tooltipTotal {
  padding-block-start: var(--space-1);
  border-block-start: 1px solid var(--border);
}

.tableWrap {
  max-block-size: 18rem;
  overflow: auto;
}

/* "No data": the pill sits on an empty plot (or spark) of faint lines. */
.badge {
  position: absolute;
  inset-block-start: 50%;
  inset-inline-start: 50%;
  translate: -50% -50%;
  padding: 0 var(--space-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-pill);
  background: var(--card);
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  color: var(--muted-foreground);
  white-space: nowrap;
}

.plot:has(> .badge) {
  background: repeating-linear-gradient(to bottom, transparent 0 calc(var(--space-12) - 1px), var(--border) calc(var(--space-12) - 1px) var(--space-12));
}

/* Sparkline */
.spark {
  position: relative;
  block-size: var(--space-12);
}

.spark svg {
  display: block;
  inline-size: 100%;
  block-size: 100%;
}

.sparkLine,
.sparkEmpty {
  fill: none;
  stroke-width: 1.25;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}

.sparkArea {
  fill-opacity: 0.07;
}

.sparkEmpty {
  stroke: var(--border);
  stroke-width: 1.5;
}

.srOnly {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* Animate in, on first draw only: lines draw left to right, bars grow from
   the axis one after another, a pie sweeps round. Reduced motion zeroes
   --duration-slow, which zeroes all of it. */
.entering .line {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  animation: draw calc(var(--duration-slow) * 2) ease-out forwards;
}

.entering .area,
.entering .lineDashed {
  opacity: 0;
  animation: fade calc(var(--duration-slow) * 1.5) ease-out calc(var(--duration-slow) * 1.2) forwards;
}

.entering .bar {
  transform-box: fill-box;
  transform-origin: 50% 100%;
  animation: grow calc(var(--duration-slow) * 2) ease-out both;
  animation-delay: calc(var(--i, 0) * var(--duration-slow) / 25);
}

.entering .sweep {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  animation: draw calc(var(--duration-slow) * 2.5) ease-out forwards;
}

.spark svg {
  animation: fade calc(var(--duration-slow) * 1.5) ease-out both;
}

@keyframes draw {
  to {
    stroke-dashoffset: 0;
  }
}

@keyframes fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes grow {
  from {
    transform: scaleY(0);
  }
}

'use client'

import { useEffect, useId, useState, type ReactNode } from 'react'
import { cn } from '@/lib/utils'
import { Button } from '../buttons/Button'
import styles from './Chart.module.css'

/** Animate in once, when there is something to draw; never again on new data. */
export function useEnterOnce(isReady: boolean) {
  const [isEntering, setIsEntering] = useState(true)
  useEffect(() => {
    if (!isReady || !isEntering) return
    const t = setTimeout(() => setIsEntering(false), 1000)
    return () => clearTimeout(t)
  }, [isReady, isEntering])
  return isEntering
}

interface ChartFrameProps {
  title: string
  isLoading: boolean
  /** The skeleton shown while loading, sized like the chart. */
  loading: ReactNode
  /** False shows "No data" in a box this tall instead of the chart. */
  hasData: boolean
  emptyHeight: number
  /** Built only when the viewer asks for it. */
  table: () => ReactNode
  className?: string
  /** The chart, given the title's id for its accessible name. */
  children: (titleId: string) => ReactNode
}

/**
 * What every chart shares around its plot: the title, the "View as table"
 * toggle and its table, and the loading and "No data" states.
 */
export function ChartFrame({ title, isLoading, loading, hasData, emptyHeight, table, className, children }: ChartFrameProps) {
  const id = useId()
  const [showTable, setShowTable] = useState(false)
  const canShowTable = hasData && !isLoading
  return (
    <figure className={cn(styles.chart, className)} aria-labelledby={`${id}-title`} aria-busy={isLoading || undefined}>
      <div className={styles.header}>
        <div id={`${id}-title`} className={styles.title}>
          {title}
        </div>
        {canShowTable && (
          <Button appearance="ghost" variant="secondary" size="sm" aria-expanded={showTable} aria-controls={`${id}-table`} onClick={() => setShowTable((v) => !v)}>
            {showTable ? 'View as chart' : 'View as table'}
          </Button>
        )}
      </div>
      {isLoading ? (
        loading
      ) : !hasData ? (
        <div className={styles.plot} style={{ blockSize: emptyHeight }}>
          <span className={styles.badge}>No data</span>
        </div>
      ) : showTable ? (
        // Focusable so a keyboard can scroll a long table.
        <div id={`${id}-table`} className={styles.tableWrap} role="region" aria-labelledby={`${id}-title`} tabIndex={0}>
          {table()}
        </div>
      ) : (
        children(`${id}-title`)
      )}
    </figure>
  )
}

import type { CSSProperties } from 'react'
import { cn } from '@/lib/utils'
import styles from './Chart.module.css'

export interface ChartLegendItem {
  key: string
  label: string
  /** A CSS colour, usually from `colorVar`. */
  color: string
  /** Shown after the label, e.g. the series total "2.56K". */
  value?: string
}

export interface ChartLegendProps {
  items: ChartLegendItem[]
  /** Keys of series that are switched off. */
  hiddenKeys?: string[]
  /** Makes each item a toggle button. Without it the legend is a plain list. */
  onToggle?: (key: string) => void
  /** Called with the key under the pointer or focus, null when it leaves. Charts use it to fade the other series. */
  onFocusChange?: (key: string | null) => void
  orientation?: 'horizontal' | 'vertical'
  className?: string
}

/** Swatch, label and value per series. As toggles, it shows and hides series in the chart above it. */
export function ChartLegend({ items, hiddenKeys = [], onToggle, onFocusChange, orientation = 'horizontal', className }: ChartLegendProps) {
  const visibleCount = items.length - hiddenKeys.length
  return (
    <ul
      className={cn(styles.legend, orientation === 'vertical' && styles.legendVertical, className)}
      aria-label="Legend"
      onPointerLeave={() => onFocusChange?.(null)}
    >
      {items.map((item) => {
        const isHidden = hiddenKeys.includes(item.key)
        const content = (
          <>
            <span className={styles.swatch} style={{ '--swatch': item.color } as CSSProperties} aria-hidden="true" />
            <span className={styles.legendLabel}>{item.label}</span>
            {item.value !== undefined && <span className={styles.legendValue}>{item.value}</span>}
          </>
        )
        const focus = () => onFocusChange?.(isHidden ? null : item.key)
        const blur = () => onFocusChange?.(null)
        return (
          <li key={item.key} onPointerEnter={focus}>
            {onToggle ? (
              <button
                type="button"
                className={styles.legendItem}
                aria-pressed={!isHidden}
                // The last visible series cannot be hidden: an empty chart reads as "no data".
                aria-disabled={!isHidden && visibleCount === 1 ? true : undefined}
                onClick={() => (!isHidden && visibleCount === 1 ? undefined : onToggle(item.key))}
                onFocus={focus}
                onBlur={blur}
              >
                {content}
              </button>
            ) : (
              <span className={styles.legendItem}>{content}</span>
            )}
          </li>
        )
      })}
    </ul>
  )
}

'use client'

import { useCallback, useId, useState, type CSSProperties } from 'react'
import { scaleBand, scaleLinear, scaleTime, scaleUtc } from 'd3-scale'
import { area, line, stack } from 'd3-shape'
import { cn } from '@/lib/utils'
import { Table } from '../data-display/Table'
import { Skeleton } from '../loaders/Skeleton'
import { ChartFrame, useEnterOnce } from './ChartFrame'
import { ChartLegend } from './ChartLegend'
import { colorVar, formatCompact, formatTime, paletteColor, type ChartSeries } from './chart-utils'
import styles from './Chart.module.css'

export type ChartRow = Record<string, unknown>

/** What LineChart and BarChart share. */
export interface CartesianChartProps {
  /** Shown above the chart, and its accessible name. */
  title: string
  /** Flat rows, one per bucket: `{ time, ok: 120, error: 4 }`. A missing or null value is a gap, not a zero. */
  data: ChartRow[]
  series: ChartSeries[]
  /** The field holding each row's x value. Dates give a time axis, strings a category axis. */
  x: string
  /** Height of the plot in pixels. The width follows the container. */
  height?: number
  /** Formats values on the axis, legend, tooltip and table. Defaults to compact numbers ("3.15K"). */
  format?: (value: number) => string
  /**
   * The time axis is in the viewer's time zone, or UTC. ponytail: no other named
   * zones, since d3 ticks only on local or UTC hours; add one when a product needs it.
   */
  timeZone?: 'UTC'
  /** The last bucket is still filling: drawn dashed (line) or faded (bar). */
  isIncomplete?: boolean
  /** What the legend shows beside each series: its sum, or its latest value (for rates and latencies, where a sum means nothing). */
  legendValue?: 'total' | 'latest'
  isLoading?: boolean
  className?: string
}

interface Props extends CartesianChartProps {
  type: 'line' | 'area' | 'bar'
  isGrouped?: boolean
  /** Fit the y axis to the data instead of starting at zero. */
  isAutoDomain?: boolean
}

const MARGIN = { top: 8, right: 8, bottom: 24 }
const DASH = '–'

/* A callback ref, so the observer follows the plot when it unmounts and comes
   back (loading, or the table view) instead of watching a detached node. */
function useWidth() {
  const [width, setWidth] = useState(0)
  const ref = useCallback((el: HTMLDivElement | null) => {
    if (!el) return
    // Measure now: the observer's first report waits for a frame, which a background tab may never paint.
    setWidth(Math.round(el.getBoundingClientRect().width))
    const observer = new ResizeObserver(([entry]) => setWidth(Math.round(entry.contentRect.width)))
    observer.observe(el)
    return () => observer.disconnect()
  }, [])
  return [ref, width] as const
}

/** A number, or null for a gap (missing, null or not a number). */
function read(row: ChartRow, key: string) {
  const v = row[key]
  return v === null || v === undefined || v === '' || Number.isNaN(Number(v)) ? null : Number(v)
}

export function CartesianChart({
  type,
  isGrouped = false,
  isAutoDomain = false,
  title,
  data,
  series,
  x,
  height = 240,
  format = formatCompact,
  timeZone,
  isIncomplete = false,
  legendValue = 'total',
  isLoading = false,
  className,
}: Props) {
  const id = useId()
  const [plotRef, width] = useWidth()
  const [hiddenKeys, setHiddenKeys] = useState<string[]>([])
  const [focusKey, setFocusKey] = useState<string | null>(null)
  const [hover, setHover] = useState<number | null>(null)
  const isEntering = useEnterOnce(width > 0 && !isLoading && data.length > 0)

  const colored = series.map((s, i) => ({ ...s, fill: colorVar(s.color ?? paletteColor(i)) }))
  // Keys left over from a previous `series` are ignored, and hiding them all shows them all.
  const hidden = hiddenKeys.filter((k) => series.some((s) => s.key === k))
  const visible = hidden.length === series.length ? colored : colored.filter((s) => !hidden.includes(s.key))
  const keys = visible.map((s) => s.key)
  const focus = focusKey && keys.includes(focusKey) ? focusKey : null
  const value = (row: ChartRow, key: string) => read(row, key) ?? 0
  const show = (row: ChartRow, key: string) => {
    const v = read(row, key)
    return v === null ? DASH : format(v)
  }
  const last = data.length - 1
  // A time axis needs two dates in order; anything else is read as categories.
  const isTime = data.length > 1 && data[0][x] instanceof Date && data[1][x] instanceof Date && +(data[1][x] as Date) > +(data[0][x] as Date)
  const xLabel = (row: ChartRow) => (isTime ? formatTime(row[x] as Date, timeZone) : String(row[x]))
  const isStacked = type === 'bar' && !isGrouped
  const totals = data.map((r) => (isStacked ? keys.reduce((s, k) => s + value(r, k), 0) : Math.max(0, ...keys.map((k) => value(r, k)))))

  const legendItems = colored.map((s) => {
    const values = data.map((r) => read(r, s.key)).filter((v): v is number => v !== null)
    const shown = legendValue === 'latest' ? values.at(-1) : values.reduce((sum, v) => sum + v, 0)
    return { key: s.key, label: s.label, color: s.fill, value: shown === undefined ? DASH : format(shown) }
  })

  const plot = (titleId: string) => {
    if (width === 0) return null
    const present = data.flatMap((r) => keys.map((k) => read(r, k))).filter((v): v is number => v !== null)
    const yMin = isAutoDomain && present.length ? Math.min(...present) : 0
    const tickCount = Math.max(3, Math.round((height - 40) / 50))
    const y = scaleLinear()
      .domain([yMin, Math.max(...totals, yMin + 1)])
      .nice(tickCount)
    const yTicks = y.ticks(tickCount)
    // ponytail: label width guessed from character count; measure the text if long units start to clip.
    const left = Math.max(...yTicks.map((t) => format(t).length)) * 7 + 12
    const innerW = Math.max(1, width - left - MARGIN.right)
    const innerH = height - MARGIN.top - MARGIN.bottom
    y.range([MARGIN.top + innerH, MARGIN.top])
    const base = y(y.domain()[0])

    // Each row's bucket: its left edge and width. A point (line on time) has width 0.
    let bucketLeft: (i: number) => number
    let bucketW: number
    let xTicks: { pos: number; label: string }[]
    let indexAt: (px: number) => number
    if (isTime) {
      const t0 = +(data[0][x] as Date)
      // ponytail: assumes evenly spaced buckets, as analytics APIs return them.
      const step = +(data[1][x] as Date) - t0
      // Ticks land on whole hours of the zone the labels are in.
      const xs = (timeZone === 'UTC' ? scaleUtc : scaleTime)()
        .domain([new Date(t0), new Date(+(data[last][x] as Date) + (type === 'bar' ? step : 0))])
        .range([left, left + innerW])
      bucketW = type === 'bar' ? xs(new Date(t0 + step)) - xs(new Date(t0)) : 0
      bucketLeft = (i) => xs(data[i][x] as Date)
      xTicks = xs
        .ticks(Math.max(2, Math.floor(innerW / 130)))
        .map((d) => ({ pos: xs(d), label: formatTime(d, timeZone) }))
        .filter((t) => t.pos - 45 >= 0 && t.pos + 45 <= width)
      indexAt = (px) => {
        const offset = (+xs.invert(px) - t0) / step
        return type === 'bar' ? Math.floor(offset) : Math.round(offset)
      }
    } else {
      const xb = scaleBand()
        .domain(data.map((_, i) => String(i)))
        .range([left, left + innerW])
        .paddingInner(type === 'bar' ? 0.3 : 0)
        .paddingOuter(type === 'bar' ? 0.15 : 0)
      bucketW = xb.bandwidth()
      bucketLeft = (i) => xb(String(i)) ?? 0
      // Every label that fits, at about 70px each; the rest are skipped evenly.
      const every = Math.ceil(data.length / Math.max(1, Math.floor(innerW / 70)))
      xTicks = data.flatMap((r, i) => (i % every ? [] : [{ pos: bucketLeft(i) + bucketW / 2, label: String(r[x]) }]))
      indexAt = (px) => Math.floor((px - left) / (innerW / data.length))
    }
    const center = (i: number) => bucketLeft(i) + bucketW / 2
    const gap = isTime ? Math.max(1, bucketW * 0.25) : 0
    const dimmed = (key: string) => cn(styles.series, focus && focus !== key && styles.dim)

    let marks
    if (isStacked) {
      marks = stack<ChartRow>()
        .keys(keys)
        .value((r, k) => value(r, k))(data)
        .map((layer, li) => (
          <g key={layer.key} className={dimmed(layer.key)} fill={visible[li].fill}>
            {layer.map(([y0, y1], i) =>
              y(y0) - y(y1) < 0.5 ? null : (
                <rect
                  key={i}
                  className={cn(styles.bar, isIncomplete && i === last && styles.partial)}
                  style={{ '--i': i } as CSSProperties}
                  x={bucketLeft(i) + gap / 2}
                  y={y(y1)}
                  width={Math.max(1, bucketW - gap)}
                  height={y(y0) - y(y1)}
                />
              ),
            )}
          </g>
        ))
    } else if (type === 'bar') {
      const inner = scaleBand()
        .domain(keys)
        .range([gap / 2, bucketW - gap / 2])
        .padding(0.12)
      marks = visible.map((s) => (
        <g key={s.key} className={dimmed(s.key)} fill={s.fill}>
          {data.map((r, i) => (
            <rect
              key={i}
              className={cn(styles.bar, isIncomplete && i === last && styles.partial)}
              style={{ '--i': i } as CSSProperties}
              x={bucketLeft(i) + (inner(s.key) ?? 0)}
              y={y(value(r, s.key))}
              width={inner.bandwidth()}
              height={base - y(value(r, s.key))}
            />
          ))}
        </g>
      ))
    } else {
      marks = visible.map((s) => {
        const isPresent = (r: ChartRow) => read(r, s.key) !== null
        const path = (from: number) =>
          line<ChartRow>()
            .defined(isPresent)
            .x((_, i) => center(i + from))
            .y((r) => y(value(r, s.key)))
        const solid = isIncomplete ? data.slice(0, last) : data
        return (
          <g key={s.key} className={dimmed(s.key)}>
            {type === 'area' && (
              <path
                className={styles.area}
                fill={s.fill}
                d={
                  area<ChartRow>()
                    .defined(isPresent)
                    .x((_, i) => center(i))
                    .y0(base)
                    .y1((r) => y(value(r, s.key)))(data) ?? ''
                }
              />
            )}
            <path className={styles.line} pathLength={1} stroke={s.fill} d={path(0)(solid) ?? ''} />
            {isIncomplete && <path className={styles.lineDashed} stroke={s.fill} d={path(last - 1)(data.slice(last - 1)) ?? ''} />}
          </g>
        )
      })
    }

    // ponytail: a hover re-renders every mark; memoise them if charts grow past a few thousand points.
    const h = hover !== null && Number.isFinite(hover) ? Math.min(last, Math.max(0, hover)) : null
    const cursorW = isTime ? bucketW : innerW / data.length
    return (
      <>
        <svg
          role="img"
          aria-labelledby={`${titleId} ${id}-range`}
          width={width}
          height={height}
          viewBox={`0 0 ${width} ${height}`}
          onPointerMove={(e) => {
            const px = e.clientX - e.currentTarget.getBoundingClientRect().left
            setHover(px < left || px > left + innerW ? null : indexAt(px))
          }}
          onPointerLeave={() => setHover(null)}
        >
          {yTicks.map((t) => (
            <g key={t}>
              <line className={styles.grid} x1={left} x2={left + innerW} y1={y(t)} y2={y(t)} />
              <text className={styles.axis} x={left - 8} y={y(t)} dy="0.32em" textAnchor="end">
                {format(t)}
              </text>
            </g>
          ))}
          {xTicks.map((t, i) => (
            <g key={i}>
              <line className={styles.tick} x1={t.pos} x2={t.pos} y1={MARGIN.top + innerH} y2={MARGIN.top + innerH + 4} />
              <text className={styles.axis} x={t.pos} y={height - 6} textAnchor="middle">
                {t.label}
              </text>
            </g>
          ))}
          {h !== null && type === 'bar' && <rect className={styles.cursorBand} x={center(h) - cursorW / 2} y={MARGIN.top} width={cursorW} height={innerH} />}
          {marks}
          {h !== null && type !== 'bar' && (
            <g>
              <line className={styles.cursor} x1={center(h)} x2={center(h)} y1={MARGIN.top} y2={MARGIN.top + innerH} />
              {visible.map((s) =>
                read(data[h], s.key) === null ? null : (
                  <circle key={s.key} className={styles.dot} cx={center(h)} cy={y(value(data[h], s.key))} r={3.5} fill={s.fill} />
                ),
              )}
            </g>
          )}
        </svg>
        <span id={`${id}-range`} className={styles.srOnly}>
          {xLabel(data[0])} to {xLabel(data[last])}. Use View as table to read the values.
        </span>
        {h !== null && (
          // Hidden from assistive tech: the table is the accessible way to read values.
          <div
            className={cn(styles.tooltip, center(h) > width / 2 && styles.tooltipFlip)}
            style={{ insetInlineStart: center(h), insetBlockStart: MARGIN.top }}
            aria-hidden="true"
          >
            <div className={styles.tooltipHead}>
              {xLabel(data[h])}
              {isIncomplete && h === last && ' · partial'}
            </div>
            {(isStacked ? [...visible].reverse() : visible).map((s) => (
              <div key={s.key} className={styles.tooltipRow}>
                <span className={styles.swatch} style={{ '--swatch': s.fill } as CSSProperties} />
                {s.label}
                <b>{show(data[h], s.key)}</b>
              </div>
            ))}
            {isStacked && visible.length > 1 && (
              <div className={cn(styles.tooltipRow, styles.tooltipTotal)}>
                Total<b>{format(totals[h])}</b>
              </div>
            )}
          </div>
        )}
      </>
    )
  }

  return (
    <ChartFrame
      title={title}
      isLoading={isLoading}
      loading={<Skeleton isFullWidth height={height} />}
      hasData={data.length > 0}
      emptyHeight={height}
      className={className}
      table={() => (
        <Table
          caption={title}
          density="sm"
          hasStickyHeader
          rows={data}
          getRowId={(_, i) => String(i)}
          columns={[
            { key: '__x', header: isTime ? 'Time' : 'Category', cell: xLabel, isRowHeader: true },
            ...series.map((s) => ({ key: s.key, header: s.label, align: 'end' as const, cell: (r: ChartRow) => show(r, s.key) })),
          ]}
        />
      )}
    >
      {(titleId) => (
        <>
          <ChartLegend
            items={legendItems}
            hiddenKeys={hidden.length === series.length ? [] : hidden}
            onToggle={(key) => {
              setFocusKey(null)
              setHiddenKeys((current) => (current.includes(key) ? current.filter((k) => k !== key) : [...current, key]))
            }}
            onFocusChange={setFocusKey}
          />
          <div ref={plotRef} className={cn(styles.plot, isEntering && styles.entering)} style={{ blockSize: height }}>
            {plot(titleId)}
          </div>
        </>
      )}
    </ChartFrame>
  )
}

