import { CartesianChart, type CartesianChartProps } from './CartesianChart'

export interface BarChartProps extends CartesianChartProps {
  /** `stacked` adds series into one bar per bucket; `grouped` puts them side by side. */
  layout?: 'stacked' | 'grouped'
}

/** Amounts per bucket or category, stacked or grouped, with a tooltip and a table view. The y axis always starts at zero. */
export function BarChart({ layout = 'stacked', ...props }: BarChartProps) {
  return <CartesianChart {...props} type="bar" isGrouped={layout === 'grouped'} />
}

'use client'

import { useId, useState } from 'react'
import { arc, pie } from 'd3-shape'
import { cn } from '@/lib/utils'
import { Table } from '../data-display/Table'
import { Skeleton } from '../loaders/Skeleton'
import { ChartFrame, useEnterOnce } from './ChartFrame'
import { ChartLegend } from './ChartLegend'
import { colorVar, formatCompact, formatShare, groupSlices, type Slice } from './chart-utils'
import styles from './Chart.module.css'

export interface PieChartProps {
  /** Shown above the chart, and its accessible name. */
  title: string
  data: Slice[]
  /** `donut` leaves a hole with the total in it. */
  appearance?: 'pie' | 'donut'
  /** Under the total in a donut, e.g. "requests". */
  centerLabel?: string
  /** Diameter in pixels. */
  size?: number
  format?: (value: number) => string
  isLoading?: boolean
  className?: string
}

/**
 * Parts of one whole. No labels on the slices: the legend beside it carries
 * value and share. Past six slices, or under 3%, slices merge into "Other".
 */
export function PieChart({
  title,
  data,
  appearance = 'pie',
  centerLabel = 'Total',
  size = 200,
  format = formatCompact,
  isLoading = false,
  className,
}: PieChartProps) {
  const id = useId()
  const [focusKey, setFocusKey] = useState<string | null>(null)
  const total = data.reduce((sum, d) => sum + d.value, 0)
  // All zeros is no data: a pie of nothing has no parts to show.
  const hasData = total > 0
  const isEntering = useEnterOnce(!isLoading && hasData)
  const shareOf = (value: number) => formatShare(value / total)

  const slices = groupSlices(data)
  const isDonut = appearance === 'donut'
  const radius = size / 2 - 2
  const arcs = pie<(typeof slices)[number]>()
    .sort(null)
    .value((d) => d.value)(slices)
  const path = arc<(typeof arcs)[number]>()
    .innerRadius(isDonut ? radius * 0.64 : 0)
    .outerRadius(radius)
    .padAngle(isDonut ? 0.015 : 0)
    .cornerRadius(isDonut ? 2 : 0)

  return (
    <ChartFrame
      title={title}
      isLoading={isLoading}
      loading={<Skeleton appearance="circle" width={size} height={size} />}
      hasData={hasData}
      emptyHeight={size}
      className={className}
      table={() => (
        <Table
          caption={title}
          density="sm"
          rows={data}
          getRowId={(_, i) => String(i)}
          columns={[
            { key: 'label', header: 'Label', isRowHeader: true },
            { key: 'value', header: 'Value', align: 'end', cell: (d) => format(d.value) },
            { key: 'share', header: 'Share', align: 'end', cell: (d) => shareOf(d.value) },
          ]}
        />
      )}
    >
      {(titleId) => (
        <div className={styles.pieBody}>
          <svg
            role="img"
            aria-labelledby={`${titleId} ${id}-desc`}
            className={cn(isEntering && styles.entering)}
            width={size}
            height={size}
            viewBox={`${-size / 2} ${-size / 2} ${size} ${size}`}
          >
            {/* The sweep-in: a ring stroke drawn round the mask, once. */}
            <mask id={`${id}-sweep`}>
              <circle className={styles.sweep} r={radius / 2} fill="none" stroke="white" strokeWidth={radius + 4} pathLength={1} transform="rotate(-90)" />
            </mask>
            <g mask={isEntering ? `url(#${id}-sweep)` : undefined}>
              {arcs.map((a, i) => (
                <path
                  key={i}
                  className={cn(styles.slice, focusKey && focusKey !== String(i) && styles.dim)}
                  d={path(a) ?? ''}
                  fill={colorVar(a.data.color)}
                  onPointerEnter={() => setFocusKey(String(i))}
                  onPointerLeave={() => setFocusKey(null)}
                />
              ))}
            </g>
            {isDonut && (
              <>
                <text className={styles.centerTotal} textAnchor="middle" dy="-0.05em">
                  {format(total)}
                </text>
                <text className={styles.centerLabel} textAnchor="middle" dy="1.5em">
                  {centerLabel}
                </text>
              </>
            )}
          </svg>
          <span id={`${id}-desc`} className={styles.srOnly}>
            {slices.map((s) => `${s.label} ${shareOf(s.value)}`).join(', ')}
          </span>
          <ChartLegend
            orientation="vertical"
            items={slices.map((s, i) => ({ key: String(i), label: s.label, color: colorVar(s.color), value: `${format(s.value)} · ${shareOf(s.value)}` }))}
            onFocusChange={setFocusKey}
          />
        </div>
      )}
    </ChartFrame>
  )
}

import type { ComponentProps } from 'react'
import { cn } from '@/lib/utils'
import { colorVar, type ChartColor } from './chart-utils'
import styles from './Chart.module.css'

export interface SparklineProps extends Omit<ComponentProps<'div'>, 'children'> {
  /** Values in order, oldest first. Empty or null shows "No data". */
  data: number[] | null | undefined
  color?: ChartColor
  /** `area` fills under the line. */
  appearance?: 'line' | 'area'
  /**
   * Off by default: next to a figure and its change the trend is decoration.
   * Give it a name when the spark is the only place the trend is shown.
   */
  'aria-label'?: string
}

/**
 * A trend with no axes, sized by its container. The viewBox stretches to any
 * width without measuring, and non-scaling-stroke keeps the line 1.25px.
 */
export function Sparkline({ data, color = 'chart-1', appearance = 'area', className, 'aria-label': ariaLabel, ...props }: SparklineProps) {
  const isEmpty = !data?.length
  let line = ''
  if (!isEmpty) {
    // A zero baseline: a spark that starts at its minimum exaggerates small swings.
    const max = Math.max(...data, 0) || 1
    const step = data.length > 1 ? 100 / (data.length - 1) : 0
    line = 'M' + data.map((v, i) => `${(i * step).toFixed(2)},${(29 - (v / max) * 27).toFixed(2)}`).join('L')
    if (data.length === 1) line += 'L100,' + line.split(',')[1]
  }
  return (
    <div {...props} className={cn(styles.spark, className)}>
      <svg viewBox="0 0 100 30" preserveAspectRatio="none" {...(ariaLabel ? { role: 'img', 'aria-label': ariaLabel } : { 'aria-hidden': true })}>
        {isEmpty ? (
          <path className={styles.sparkEmpty} d="M0,20 C25,14 40,24 60,18 S90,12 100,16" />
        ) : (
          <>
            {appearance === 'area' && <path className={styles.sparkArea} d={`${line}L100,30L0,30Z`} fill={colorVar(color)} />}
            <path className={styles.sparkLine} d={line} stroke={colorVar(color)} />
          </>
        )}
      </svg>
      {isEmpty && <span className={styles.badge}>No data</span>}
    </div>
  )
}
